// Title: How to embed custom CSS styling for SVG path elements when exporting an Excel worksheet to SVG with Aspose.Cells for .NET (C#)
// Common Searches: Aspose.Cells C# export worksheet to SVG and add custom stroke style to path elements | Insert a CSS <style> block into SVG output generated by SheetRender in Aspose.Cells | Change SVG path color and width after exporting an Excel sheet with Aspose.Cells .NET | C# code to modify generated SVG file from Aspose.Cells to include custom CSS for paths | Add custom CSS to SVG exported from an Excel workbook using Aspose.Cells for .NET
// Tags: Aspose.Cells SheetRender SVG export | add CSS to generated SVG C# | customize SVG path stroke Aspose.Cells | insert style element after opening svg tag | modify SVG content post render Aspose.Cells

using Aspose.Cells;
using Aspose.Cells.Drawing;
using Aspose.Cells.Rendering;
using System;
using System.IO;
using System.Text;

// The example loads an Excel workbook, uses Aspose.Cells SheetRender to export the first worksheet as SVG, reads the SVG text, inserts a <style> block that sets path stroke color, width, and fill, and saves the modified SVG file.
class Program
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.svg";

            // Ensure the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Input file \"{inputPath}\" not found.");
                return;
            }

            // Load the workbook
            Workbook workbook = new Workbook(inputPath);
            Worksheet worksheet = workbook.Worksheets[0];

            // Configure image save options for SVG
            ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
            {
                SaveFormat = SaveFormat.Svg,
                OnePagePerSheet = true // export the whole sheet as a single page
            };

            // Export the worksheet to SVG using a memory stream
            using (MemoryStream svgStream = new MemoryStream())
            {
                // Render the worksheet as an image (SVG) into the stream
                SheetRender renderer = new SheetRender(worksheet, imgOptions);
                renderer.ToImage(0, svgStream);
                svgStream.Position = 0;

                // Read the generated SVG content as text
                string svgContent;
                using (StreamReader reader = new StreamReader(svgStream, Encoding.UTF8))
                {
                    svgContent = reader.ReadToEnd();
                }

                // CSS block to be inserted after the opening <svg> tag
                string cssBlock = @"
    <style type='text/css'>
        path { stroke:#ff0000; stroke-width:2; fill:none; }
    </style>";

                // Insert the CSS block right after the opening <svg> tag
                int insertPos = svgContent.IndexOf('>') + 1;
                if (insertPos > 0 && insertPos < svgContent.Length)
                {
                    svgContent = svgContent.Insert(insertPos, cssBlock);
                }

                // Write the modified SVG to a file
                File.WriteAllText(outputPath, svgContent, Encoding.UTF8);
                Console.WriteLine($"SVG file saved to \"{outputPath}\".");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
